from django.db import migrations

SQL="\n-- R4: task-side verification runs at COMMIT, after ManagerAttestation and\n-- TaskCompletion can be inserted in either order within the same transaction.\n-- A trigger ONLY on the evidence row cannot prevent a naked Task UPDATE.\nCREATE OR REPLACE FUNCTION public.m2_validate_completed_task()\nRETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$\nDECLARE t public.onboarding_task%ROWTYPE;\nBEGIN\n SELECT * INTO t FROM public.onboarding_task WHERE id=NEW.id;\n IF t.execution_state='COMPLETED' THEN\n   IF t.kind IS DISTINCT FROM 'MANAGER_PREPARATION'\n      OR t.completed_at IS NULL\n      OR NOT EXISTS (\n        SELECT 1 FROM public.onboarding_taskcompletion c\n        JOIN public.onboarding_managerattestation a\n          ON a.id=c.manager_attestation_id\n        WHERE c.task_id=t.id AND a.task_id=t.id\n          AND c.evidence_type='MANAGER_PREPARATION'\n          AND a.actor_id=c.completed_by_id\n          AND c.completed_at IS NOT NULL\n      )\n   THEN\n     RAISE EXCEPTION 'M2 completed task lacks accepted evidence'\n       USING ERRCODE='23514';\n   END IF;\n END IF;\n RETURN NULL;\nEND; $$;\n\nCREATE CONSTRAINT TRIGGER m2_task_evidence_invariant\nAFTER INSERT OR UPDATE ON public.onboarding_task\nDEFERRABLE INITIALLY DEFERRED\nFOR EACH ROW EXECUTE FUNCTION public.m2_validate_completed_task();\n\n-- R5: task creation snapshot fields include availability and due schedule;\n-- even a privileged ordinary ORM UPDATE must not silently reschedule them.\nCREATE OR REPLACE FUNCTION public.m2_guard_task_snapshot()\nRETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$\nDECLARE cstatus text; cversion uuid; tv uuid;\nBEGIN\n IF TG_OP='DELETE' THEN\n   RAISE EXCEPTION 'M2 task snapshot may not be deleted' USING ERRCODE='23514';\n END IF;\n IF TG_OP='UPDATE' THEN\n   IF (NEW.case_id,NEW.template_task_id,NEW.key,NEW.kind,NEW.title,\n       NEW.description,NEW.owner_role,NEW.required,NEW.applicable,NEW.evidence_spec,\n       NEW.available_at,NEW.due_at)\n      IS DISTINCT FROM\n      (OLD.case_id,OLD.template_task_id,OLD.key,OLD.kind,OLD.title,\n       OLD.description,OLD.owner_role,OLD.required,OLD.applicable,OLD.evidence_spec,\n       OLD.available_at,OLD.due_at)\n   THEN RAISE EXCEPTION 'M2 task snapshot identity/schedule immutable'\n        USING ERRCODE='23514';\n   END IF;\n   IF OLD.execution_state IN ('COMPLETED','CANCELLED')\n       AND (NEW.execution_state IS DISTINCT FROM OLD.execution_state\n            OR NEW.completed_at IS DISTINCT FROM OLD.completed_at\n            OR NEW.work_started_at IS DISTINCT FROM OLD.work_started_at)\n   THEN RAISE EXCEPTION 'M2 terminal task evidence metadata immutable'\n        USING ERRCODE='23514';\n   END IF;\n   RETURN NEW;\n END IF;\n SELECT status,template_version_id INTO cstatus,cversion\n   FROM public.onboarding_onboardingcase WHERE id=NEW.case_id FOR SHARE;\n SELECT version_id INTO tv FROM public.templates_templatetask\n   WHERE id=NEW.template_task_id FOR SHARE;\n IF cstatus IS DISTINCT FROM 'CREATED' OR tv IS DISTINCT FROM cversion THEN\n   RAISE EXCEPTION 'M2 task must instantiate on matching CREATED case'\n     USING ERRCODE='23514';\n END IF;\n RETURN NEW;\nEND; $$;\n\nCREATE OR REPLACE FUNCTION public.m2_guard_case_template_binding()\nRETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$\nBEGIN\n IF (OLD.status IS DISTINCT FROM 'CREATED' OR NEW.status IS DISTINCT FROM 'CREATED')\n    AND NEW.template_version_id IS DISTINCT FROM OLD.template_version_id THEN\n    RAISE EXCEPTION 'M2 activated case template binding immutable'\n      USING ERRCODE='23514';\n END IF;\n RETURN NEW;\nEND; $$;\nCREATE TRIGGER m2_case_template_immutable\nBEFORE UPDATE OF template_version_id,status\nON public.onboarding_onboardingcase\nFOR EACH ROW EXECUTE FUNCTION public.m2_guard_case_template_binding();\n"
REVERSE_SQL="\nDROP TRIGGER IF EXISTS m2_case_template_immutable ON public.onboarding_onboardingcase;\nDROP FUNCTION IF EXISTS public.m2_guard_case_template_binding();\nDROP TRIGGER IF EXISTS m2_task_evidence_invariant ON public.onboarding_task;\nDROP FUNCTION IF EXISTS public.m2_validate_completed_task();\n-- Restore the historical 0007 task snapshot guard before rollback.\nCREATE OR REPLACE FUNCTION public.m2_guard_task_snapshot()\nRETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$\nDECLARE cstatus text; cversion uuid; tv uuid;\nBEGIN\n IF TG_OP='DELETE' THEN\n   RAISE EXCEPTION 'M2 task snapshot may not be deleted' USING ERRCODE='23514';\n END IF;\n IF TG_OP='UPDATE' THEN\n   IF (NEW.case_id,NEW.template_task_id,NEW.key,NEW.kind,NEW.title,\n       NEW.description,NEW.owner_role,NEW.required,NEW.applicable,NEW.evidence_spec)\n      IS DISTINCT FROM\n      (OLD.case_id,OLD.template_task_id,OLD.key,OLD.kind,OLD.title,\n       OLD.description,OLD.owner_role,OLD.required,OLD.applicable,OLD.evidence_spec)\n   THEN RAISE EXCEPTION 'M2 task snapshot identity immutable' USING ERRCODE='23514';\n   END IF;\n   IF OLD.execution_state IN ('COMPLETED','CANCELLED')\n       AND NEW.execution_state IS DISTINCT FROM OLD.execution_state\n   THEN RAISE EXCEPTION 'M2 terminal task cannot reopen' USING ERRCODE='23514';\n   END IF;\n   RETURN NEW;\n END IF;\n SELECT status,template_version_id INTO cstatus,cversion\n   FROM public.onboarding_onboardingcase WHERE id=NEW.case_id FOR SHARE;\n SELECT version_id INTO tv FROM public.templates_templatetask\n   WHERE id=NEW.template_task_id FOR SHARE;\n IF cstatus IS DISTINCT FROM 'CREATED' OR tv IS DISTINCT FROM cversion THEN\n   RAISE EXCEPTION 'M2 task must instantiate on matching CREATED case' USING ERRCODE='23514';\n END IF;\n RETURN NEW;\nEND; $$;\n"

class Migration(migrations.Migration):
    dependencies=[('onboarding','0007_snapshot_evidence_guards')]
